    function testFuzz_property(address recipient, uint256 bonusPad) public {
        vm.assume(recipient != address(0));
        uint256 bonus = bound(bonusPad, 0, 1 ether);

        vm.deal(address(c), 1 ether);

        c.getFirstWithdrawalBonus(recipient);

        uint256 balBefore = address(c).balance;

        bool ok;
        try c.withdrawReward(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && address(c).balance == balBefore);
    }
